// === Tab: mySketch ===
// number of particles
let N = 500;

// colors (some of them taken from http://www.colourlovers.com/pattern/5526827/bleak
cols = [  
  "#FF8A00", "#FFD200", "#749D9D", "#FCF5B3", "#B39500", "#272429"
];

// collection of all particles
ArrayList<Particle> particles = new ArrayList<Particle>(N);

function setup() {
  createCanvas(700, 700);
  noFill();
  smooth(8);
  strokeWeight(0.7);
  background(0, 0, 20);

  // initialize particles
  for (i=0; i<N; i++) {
    particles.add( new Particle(i) );
  }
}

let time = 0.0001;
function draw() {
  for (let p of particles) {

    // love/hate vector
    let lovex = 0.0;
    let lovey = 0.0;

    for (let o of particles) {
      // do not compare with yourself
      if (p.id != o.id) {
        // calculate vector to get distance and direction
        let v = new PVector(o.x-p.x, o.y-p.y);
        let distance = v.mag();
        let angle = v.heading();

        // love!
        let love = 1.0 / distance;
        // or hate...
        if (distance<2.0) love = -love;

        // mood factor
        love *= p.moodSimilarity(o);
        // not too fast!
        love *= 0.5;

        // update love vector
        lovex += love * cos(angle);
        lovey += love * sin(angle);
      } 

      // calculated love vector will be our speed in resultant direction
      p.dx = lovex;
      p.dy = lovey;
    }
  }

  // update and draw
  for (let p of particles) {
    p.update();
    p.draw();
  }

  time += 0.00001;
}

class Particle {
  // position
  x, y;
  // velocity
  dx, dy;
  // id
  id;
  // life length
  age;
  // some random let color c = cols[int(random)(cols.length)];

  // mood factor
  mood;

  function reset() {
    // distribute initial point on the ring, more near the outer edge, distorted
    var angle = random(TWO_PI);
    let r = 5.0*randomGaussian() + (width/2-100)*(1.0-pow(random(1.0), 7.0));
    x = cos(angle)*r;
    y = sin(angle)*r;
    // set random age
    age = int(random)(100, 2000);
    calcMood();
  }

  function draw() {
    stroke(c,50);
    point(x+width/2, y+height/2);
  }

  // update position with externally calculated speed
  // check also age
  function update() {
    if(--age < 0) {
      reset();
    } else {
      x += dx;
      y += dy;
      calcMood();
    }
  }

  constructor(i) {
    id = i;
    reset();
  }

  // compare moods
  moodSimilarity(p) {
    return 1.0-abs(p.mood-this.mood);
  }

  // calculate current mood
  function calcMood() {
    mood = sin(noise(x/10.0,y/10.0,time)*TWO_PI); 
  }
 }

